    headers = {
        str(cell.value).strip().lower(): cell.column
        for cell in worksheet[1]
        if cell.value is not None
    }

    order_col = next(
        (headers[name] for name in ("order id", "order_id", "order number", "order")),
        None,
    )
    status_col = next(
