from pathlib import Path
from openpyxl import load_workbook

file_path = Path("./data/order_summary.xlsx")
order_id = "ORD-6C71B1"

workbook = load_workbook(file_path)
updated_cells = []

for sheet in workbook.worksheets:
    # Locate the header row and relevant columns within the first 20 rows.
    header_info = None

    for header_row in range(1, min(sheet.max_row, 20) + 1):
        headers = {
            str(cell.value).strip().lower(): cell.column
            for cell in sheet[header_row]
            if cell.value is not None
        }

        order_column = next(
            (
                headers[name]
                for name in ("order id", "order_id", "order number", "order")
                if name in headers
            ),
            None,
        )
        status_column = next(
            (
                headers[name]
                for name in ("status", "order status", "order_status")
                if name in headers
            ),
            None,
        )

        if order_column and status_column:
            header_info = (header_row, order_column, status_column)
            break

    if header_info is None:
        continue

    header_row, order_column, status_column = header_info

    for row in range(header_row + 1, sheet.max_row + 1):
        value = sheet.cell(row=row, column=order_column).value

        if str(value).strip().upper() == order_id.upper():
            status_cell = sheet.cell(row=row, column=status_column)
            current_status = str(status_cell.value).strip().lower()

            if current_status != "cancelled":
                raise ValueError(
                    f"{order_id} in sheet {sheet.title!r} has status "
                    f"{status_cell.value!r}, not 'cancelled'."
                )

            status_cell.value = "confirmed"
            updated_cells.append(f"{sheet.title}!{status_cell.coordinate}")

if not updated_cells:
    raise ValueError(f"Order {order_id} was not found in {file_path}.")

workbook.save(file_path)

# Read back the saved workbook to verify the update.
verification_workbook = load_workbook(file_path, read_only=True, data_only=False)
for location in updated_cells:
    sheet_name, coordinate = location.rsplit("!", 1)
    saved_status = verification_workbook[sheet_name][coordinate].value
    if str(saved_status).strip().lower() != "confirmed":
        raise RuntimeError(f"Verification failed for {location}: {saved_status!r}")

verification_workbook.close()
workbook.close()

print(
    f"Updated {order_id} from 'cancelled' to 'confirmed' "
    f"in {', '.join(updated_cells)}."
)

